class CommandLine_HasOptionOptionGroupTest {

    /**
     * Test helper subclass to control the behavior of hasOption(String)
     * so we can isolate testing of hasOption(OptionGroup).
     */
    static class TestableCommandLine extends CommandLine {
        String lastSeenOptionName = null;
        private final boolean returnValue;

        TestableCommandLine(boolean returnValue) {
            super(); // use protected no-arg ctor available in the same package
            this.returnValue = returnValue;
        }

        @Override
        public boolean hasOption(final String optionName) {
            this.lastSeenOptionName = optionName;
            return returnValue;
        }
    }

    @Test
    void testHasOption_NullGroup_ReturnsFalse() {
        TestableCommandLine cmd = new TestableCommandLine(true);
        // Passing null should return false and should not call hasOption(String)
        boolean result = cmd.hasOption((OptionGroup) null);
        assertFalse(result);
        assertNull(cmd.lastSeenOptionName);
    }

    @Test
    void testHasOption_GroupNotSelected_ReturnsFalse() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine(true);
        OptionGroup group = new OptionGroup(); // selected is null by default
        // Ensure isSelected() is false
        assertFalse(group.isSelected());
        boolean result = cmd.hasOption(group);
        assertFalse(result);
        // hasOption(String) should not have been called
        assertNull(cmd.lastSeenOptionName);
    }

    @Test
    void testHasOption_GroupSelected_CommandLineReturnsTrue() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine(true);
        OptionGroup group = new OptionGroup();

        // Use reflection to set the private 'selected' field on OptionGroup
        Field selectedField = OptionGroup.class.getDeclaredField("selected");
        selectedField.setAccessible(true);
        selectedField.set(group, "myOpt");

        // Sanity: now isSelected() should be true and getSelected() should return our value
        assertTrue(group.isSelected());
        assertEquals("myOpt", group.getSelected());

        boolean result = cmd.hasOption(group);
        assertTrue(result);

        // Ensure the underlying hasOption(String) was invoked with the expected string
        assertEquals("myOpt", cmd.lastSeenOptionName);
    }

    @Test
    void testHasOption_GroupSelected_CommandLineReturnsFalse() throws Exception {
        TestableCommandLine cmd = new TestableCommandLine(false);
        OptionGroup group = new OptionGroup();

        Field selectedField = OptionGroup.class.getDeclaredField("selected");
        selectedField.setAccessible(true);
        selectedField.set(group, "other");

        assertTrue(group.isSelected());
        assertEquals("other", group.getSelected());

        boolean result = cmd.hasOption(group);
        assertFalse(result);
        assertEquals("other", cmd.lastSeenOptionName);
    }

    @Test
    void testInvokePrivateConstructorViaReflection() throws Exception {
        // Access the private constructor CommandLine(List<String>, List<Option>, Consumer<Option>)
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(
                List.class, List.class, Consumer.class
        );
        ctor.setAccessible(true);

        // Instantiate with non-null lists (constructor checks requireNonNull)
        List<String> args = new LinkedList<>();
        List<Option> options = new LinkedList<>();
        // We can pass null for deprecatedHandler or a no-op consumer
        Consumer<Option> handler = (o) -> {
            // no-op
        };

        CommandLine instance = ctor.newInstance(args, options, handler);
        assertNotNull(instance);
        // Basic sanity: calling hasOption with null should return false
        assertFalse(instance.hasOption((OptionGroup) null));
    }
